INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('29000000-0000-4000-8000-050000000001', 'PASSAGE', 'A. In a fictional town, parents organised a "walking bus": a group of children walks to school together along a fixed route, led by two adult volunteers. Children join at marked stops, just as passengers board a bus.
