INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000001', '29000000-0000-4000-8000-060000000001', 1, 'What is the main idea of The walking bus?', '[{"optionKey": "A", "content": "Children walk to school together in a supervised group.", "sortOrder": 1}, {"optionKey": "B", "content": "The town has built a new road to the school.", "sortOrder": 2}, {"optionKey": "C", "content": "Children must now travel to school on a real bus.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'The passage describes how the scheme works, why it began and its plans. B and C are not stated.', 'PUBLISHED');
