INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000002', '29000000-0000-4000-8000-060000000002', 1, 'What is paragraph B mainly about?', '[{"optionKey": "A", "content": "Why the scheme started and what changed after one term.", "sortOrder": 1}, {"optionKey": "B", "content": "How the adult volunteers are chosen.", "sortOrder": 2}, {"optionKey": "C", "content": "Which roads the route follows.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'Paragraph B gives the reason (heavy traffic) and the results (fewer cars, fewer late arrivals).', 'PUBLISHED');
