INSERT INTO knowledge_points (id, topic_id, code, name, kind, learning_type, skill, description, status) VALUES ('29000000-0000-4000-8000-020000000003', '29000000-0000-4000-8000-010000000002', 'W65_DISCUSS_BOTH_VIEWS', 'Bàn hai quan điểm (Task 2)', 'STRATEGY', 'PROCEDURE', 'WRITING', 'Trình bày công bằng hai quan điểm, mỗi quan điểm một đoạn có lý do và ví dụ, rồi nêu rõ ý kiến riêng.', 'ACTIVE');
