INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000019', '29000000-0000-4000-8000-060000000019', 1, 'Some people think that university students should be free to study whatever they like. Others believe that they should only be allowed to study subjects that will be useful in the future, such as science and technology. Discuss both these views and give your own opinion. Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.', NULL, '{"type": "ESSAY", "task": "TASK_2", "minWords": 250, "passBand": 6.5}', 1, 'Whether universities should let students choose any subject or steer them towards fields with obvious practical value is a long-running debate. Both positions have merit, but I believe students should keep the freedom to choose.
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('29000000-0000-4000-8000-070000000019', '29000000-0000-4000-8000-020000000003', 1.0);
INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type, text_content) VALUES ('29000000-0000-4000-8000-040000000004', '29000000-0000-4000-8000-030000000002', 1, 'TEXT', 'Dạng "Discuss both views and give your own opinion": mỗi quan điểm một đoạn thân bài có lý do và ví dụ; ý kiến riêng nêu ở mở bài và nhắc lại ở kết luận. Đừng chỉ liệt kê, hãy giải thích vì sao mỗi lý do quan trọng.');
INSERT INTO lesson_block_knowledge_points (block_id, knowledge_point_id) VALUES ('29000000-0000-4000-8000-040000000004', '29000000-0000-4000-8000-020000000003');
INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type) VALUES ('29000000-0000-4000-8000-040000000005', '29000000-0000-4000-8000-030000000002', 2, 'EXERCISE');
INSERT INTO lesson_block_questions (block_id, question_version_id, sort_order) VALUES ('29000000-0000-4000-8000-040000000005', '29000000-0000-4000-8000-070000000019', 1);
INSERT INTO content_assets (id, asset_type, text_content, validation_status) VALUES ('29000000-0000-4000-8000-050000000002', 'PASSAGE', 'A. A fictional software company let its staff work four longer days instead of five for six months. Managers had expected tiredness to reduce output, but the number of tasks completed each week stayed close to the previous level. Sick days fell slightly, although the pilot ran during the summer, when illness is usually less common.
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('29000000-0000-4000-8000-060000000020', 'MULTIPLE_CHOICE', 'READING', 'LEARNING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000020', '29000000-0000-4000-8000-060000000020', 1, 'What can be inferred about output during the pilot?', '[{"optionKey": "A", "content": "It stayed roughly stable despite the shorter week.", "sortOrder": 1}, {"optionKey": "B", "content": "It rose sharply.", "sortOrder": 2}, {"optionKey": "C", "content": "It collapsed because staff were tired.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'Weekly completed tasks stayed close to the earlier level, so managers'' fear was not confirmed.', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('29000000-0000-4000-8000-070000000020', '28000000-0000-4000-8000-020000000001', 1.0);
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('29000000-0000-4000-8000-060000000021', 'MULTIPLE_CHOICE', 'READING', 'LEARNING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000021', '29000000-0000-4000-8000-060000000021', 1, 'Why should the fall in sick days be treated with caution?', '[{"optionKey": "A", "content": "The pilot took place in a season when illness is usually less common.", "sortOrder": 1}, {"optionKey": "B", "content": "Sick days were not recorded during the pilot.", "sortOrder": 2}, {"optionKey": "C", "content": "Staff were not allowed to take sick leave.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'The writer notes the summer timing, which offers another explanation for fewer sick days.', 'PUBLISHED');
INSERT INTO question_knowledge_points (question_version_id, knowledge_point_id, weight) VALUES ('29000000-0000-4000-8000-070000000021', '28000000-0000-4000-8000-020000000001', 1.0);
INSERT INTO questions (id, question_type, skill, purpose, status) VALUES ('29000000-0000-4000-8000-060000000022', 'MULTIPLE_CHOICE', 'READING', 'LEARNING', 'PUBLISHED');
INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000022', '29000000-0000-4000-8000-060000000022', 1, 'Which restatement matches the survey finding in paragraph B?', '[{"optionKey": "A", "content": "Every employee supported the new schedule.", "sortOrder": 1}, {"optionKey": "B", "content": "Most people who replied favoured keeping it, but the replies may overstate support.", "sortOrder": 2}, {"optionKey": "C", "content": "The survey proved that the schedule should end.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "B"}', 1, 'B keeps both the majority view and the warning about who did not reply.', 'PUBLISHED');
