INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000024', '29000000-0000-4000-8000-060000000024', 1, 'Which statement restates the company''s decision?', '[{"optionKey": "A", "content": "The four-day week became permanent for all teams.", "sortOrder": 1}, {"optionKey": "B", "content": "The arrangement continues for a year, with customer support still available on Fridays.", "sortOrder": 2}, {"optionKey": "C", "content": "The pilot ended because clients complained.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "B"}', 1, 'The decision extends the pilot for one year with a Friday exception for support.', 'PUBLISHED');
