INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES ('29000000-0000-4000-8000-070000000025', '29000000-0000-4000-8000-060000000025', 1, 'What do the client complaints suggest?', '[{"optionKey": "A", "content": "Customer support was slower when nobody worked on Fridays.", "sortOrder": 1}, {"optionKey": "B", "content": "Clients wanted a four-day week for themselves.", "sortOrder": 2}, {"optionKey": "C", "content": "Clients were unhappy with prices.", "sortOrder": 3}]', '{"type": "CHOICE", "correct": "A"}', 1, 'Complaints about slower replies explain why Friday support cover was kept.', 'PUBLISHED');
